arguments.new_string:
if ndigits is None:
    s = str(num)
else:
    if ndigits == 0:
        s = f"{int(round(num))}"
    else:
        s = f"{num:.{ndigits}f}"
if "." in s:
    int_part, dec_part = s.split(".")
else:
    int_part, dec_part = s, ""
int_part_with_commas = f"{int(int_part):,}" if int_part.isdigit() else int_part
if dec_part:
    # Do not strip zeros when ndigits is specified
    if ndigits is None:
        dec_part = dec_part.rstrip("0").rstrip(".")
    return f"{int_part_with_commas}.{dec_part}"
return int_part_with_commas

